# --------------------------- PHP value model ---------------------------
class PHPArray:
    def __init__(self, init=None):
        self.data = OrderedDict()
        self.next_index = 0
        if init:
            for k, v in init:
                if k is None:
                    self.append(v)
                else:
                    self.set(k, v)
    def _key(self, key):
        if isinstance(key, bool):
            return int(key)
        if key is None:
            return ""
        if isinstance(key, int):
            return key
        if isinstance(key, float):
            return int(key)
        if isinstance(key, str):
            # PHP converts plain decimal integer string keys to ints, except
            # strings with leading plus/leading zero forms.
            if re.fullmatch(r'-?(0|[1-9][0-9]*)', key):
                try:
                    return int(key)
                except Exception:
                    pass
            return key
        return str(key)
    def set(self, key, val):
        k = self._key(key)
        self.data[k] = val
        if isinstance(k, int) and k >= self.next_index:
            self.next_index = k + 1
    def append(self, val):
        k = self.next_index
        self.data[k] = val
        self.next_index = k + 1
        return k
    def get(self, key, default=None):
        return self.data.get(self._key(key), default)
    def exists(self, key):
        return self._key(key) in self.data
    def delete(self, key):
        self.data.pop(self._key(key), None)
    def items(self):
        return self.data.items()
    def keys(self):
        return list(self.data.keys())
    def values(self):
        return list(self.data.values())
    def __len__(self):
        return len(self.data)
    def copy(self):
        a = PHPArray()
        a.data = OrderedDict((k, php_copy(v)) for k, v in self.data.items())
        a.next_index = self.next_index
        return a
    def is_list(self):
        return list(self.data.keys()) == list(range(len(self.data)))

class PHPObject:
    _next_id = 1
    def __init__(self, class_name="stdClass"):
        self.class_name = class_name
        self.props = OrderedDict()
        self.id = PHPObject._next_id
        PHPObject._next_id += 1
    def copy(self):
        o = PHPObject(self.class_name)
        o.props = OrderedDict((k, php_copy(v)) for k, v in self.props.items())
        return o

class Cell:
