        self.line = line


def php_copy(v):
    # PHP arrays are copy-on-write; this clone is adequate for by-value passing.
    if isinstance(v, PHPArray): return v.copy()
    # Objects are reference-like in PHP.
    return v


def is_numeric_string(s):
    return re.match(r'^[\t\n\r\f\v ]*[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?', s or "")


def parse_numeric(s):
    if isinstance(s, bool): return int(s), False, True
    if isinstance(s, int): return s, False, True
    if isinstance(s, float): return s, True, True
    if s is None: return 0, False, True
    if isinstance(s, str):
        m = is_numeric_string(s)
        if not m: return 0, False, False
        num = m.group(0).strip()
        is_float = any(c in num.lower() for c in ['.', 'e'])
        try:
            return (float(num) if is_float else int(num, 10)), is_float, (m.end() == len(s.strip()) or s[m.end():].strip()=="")
        except Exception:
            return 0, False, False
    return 1 if isinstance(s, PHPObject) else 0, False, isinstance(s, PHPObject)


def php_int(v):
    if v is None: return 0
    if isinstance(v, bool): return 1 if v else 0
    if isinstance(v, int): return v
    if isinstance(v, float): return int(v)
    if isinstance(v, str): return int(parse_numeric(v)[0])
    if isinstance(v, PHPArray): return 1 if len(v) else 0
    return 1


def php_float(v):
    if v is None: return 0.0
    if isinstance(v, bool): return 1.0 if v else 0.0
    if isinstance(v, (int,float)): return float(v)
    if isinstance(v, str): return float(parse_numeric(v)[0])
    if isinstance(v, PHPArray): return 1.0 if len(v) else 0.0
    return 1.0


def php_bool(v):
    if v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, (int,float)): return v != 0 and v != 0.0
    if isinstance(v, str): return v != "" and v != "0"
    if isinstance(v, PHPArray): return len(v) != 0
    return True


def format_float(v):
    if math.isnan(v): return "NAN"
    if math.isinf(v): return "INF" if v > 0 else "-INF"
    # PHP's default precision is 14 in this build; Python's general format is close.
    s = ("%.14g" % v)
    return s


def php_string(v, rt=None, line=None):
    if v is None: return ""
    if isinstance(v, bool): return "1" if v else ""
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return format_float(v)
    if isinstance(v, str): return v
    if isinstance(v, PHPArray):
        if rt: rt.warning("Array to string conversion", line)
        return "Array"
    if isinstance(v, PHPObject):
        if hasattr(v, 'to_string'):
            return v.to_string()
        raise PHPFatal(f"Object of class {v.class_name} could not be converted to string", "Error", line)
    return str(v)


def php_key_string(k):
    return str(k)


def loose_compare(a, b):
    # Return -1/0/1, following common PHP loose comparison behavior.
    if isinstance(a, bool) or isinstance(b, bool) or a is None or b is None:
        aa = php_bool(a); bb = php_bool(b)
        return (aa > bb) - (aa < bb)
    if isinstance(a, (int,float)) or isinstance(b, (int,float)):
        aa, af, _ = parse_numeric(a)
        bb, bf, _ = parse_numeric(b)
        return (aa > bb) - (aa < bb)
    if isinstance(a, str) and isinstance(b, str):
        ma = is_numeric_string(a); mb = is_numeric_string(b)
        if ma and mb:
            aa = parse_numeric(a)[0]; bb = parse_numeric(b)[0]
            return (aa > bb) - (aa < bb)
        return (a > b) - (a < b)
    if isinstance(a, PHPArray) and isinstance(b, PHPArray):
        return (len(a)>len(b)) - (len(a)<len(b)) if len(a)!=len(b) else 0
    return (php_string(a) > php_string(b)) - (php_string(a) < php_string(b))


def strict_equal(a,b):
    if type(a) is not type(b): return False
    if isinstance(a, PHPArray):
        return list(a.items()) == list(b.items())
    return a == b

# ------------------------------- Lexer --------------------------------
class Token:
    __slots__ = ('type','value','line','col')
    def __init__(self, typ, value, line, col):
        self.type=typ; self.value=value; self.line=line; self.col=col
    def __repr__(self):
        return f"Token({self.type!r},{self.value!r},{self.line}:{self.col})"

OPERATORS = [
    '===','!==','<<=','>>=','**=','...','??=','=>','->','::','++','--','==','!=','<>','<=','>=','&&','||','<<','>>','+=','-=','*=','/=','%=','.=','&=','|=','^=','??','**'
]
SINGLE = set('{}()[];,?:.+-*/%=<>!~&|^@')

class Lexer:
    def __init__(self, text, filename="Command line code", start_line=1):
        self.text=text; self.i=0; self.line=start_line; self.col=1; self.filename=filename; self.n=len(text)
    def peek(self, n=0):
        j=self.i+n
        return self.text[j] if j<self.n else ''
    def advance(self, count=1):
        s=''
        for _ in range(count):
            if self.i>=self.n: break
            ch=self.text[self.i]; s+=ch; self.i+=1
            if ch=='\n': self.line+=1; self.col=1
            else: self.col+=1
        return s
    def skip_ws_comments(self):
        while self.i<self.n:
            ch=self.peek()
            if ch in ' \t\r\n\v\f':
                self.advance(); continue
            if ch=='/' and self.peek(1)=='/':
                while self.i<self.n and self.peek()!='\n': self.advance()
                continue
            if ch=='#':
                while self.i<self.n and self.peek()!='\n': self.advance()
                continue
            if ch=='/' and self.peek(1)=='*':
                self.advance(2)
                while self.i<self.n and not (self.peek()=='*' and self.peek(1)=='/'):
                    self.advance()
                if self.i<self.n: self.advance(2)
                continue
            break
    def read_number(self):
        line,col=self.line,self.col; start=self.i
        if self.peek()=='0' and self.peek(1).lower() in ('x','b'):
            self.advance(2)
            while re.match(r'[0-9a-fA-F]', self.peek() or ''): self.advance()
            return Token('NUMBER', self.text[start:self.i], line, col)
        while self.peek().isdigit() or self.peek()=='_': self.advance()
        if self.peek()=='.' and self.peek(1).isdigit():
            self.advance()
            while self.peek().isdigit() or self.peek()=='_': self.advance()
        if self.peek().lower()=='e' and (self.peek(1).isdigit() or (self.peek(1) in '+-' and self.peek(2).isdigit())):
            self.advance()
            if self.peek() in '+-': self.advance()
            while self.peek().isdigit() or self.peek()=='_': self.advance()
        return Token('NUMBER', self.text[start:self.i], line, col)
    def read_identifier(self):
        line,col=self.line,self.col; start=self.i
        while re.match(r'[A-Za-z0-9_\\]', self.peek() or ''): self.advance()
        return Token('ID', self.text[start:self.i], line, col)
    def read_variable(self):
        line,col=self.line,self.col; self.advance()
        if self.peek()=='{':
            return Token('$', '$', line, col)
        start=self.i
        if re.match(r'[A-Za-z_\x80-\xff]', self.peek() or ''):
            while re.match(r'[A-Za-z0-9_\x80-\xff]', self.peek() or ''): self.advance()
            return Token('VAR', self.text[start:self.i], line, col)
        return Token('$', '$', line, col)
    def read_string(self, quote):
        line,col=self.line,self.col; self.advance()
        raw=''
        while self.i<self.n:
            ch=self.peek()
            if ch==quote:
                self.advance(); break
            if ch=='\\':
                raw += self.advance()
                if self.i<self.n: raw += self.advance()
            else:
                raw += self.advance()
        return Token('STRING_D' if quote=='"' else 'STRING_S', raw, line, col)
    def next_token(self):
        self.skip_ws_comments()
        if self.i>=self.n: return Token('EOF','',self.line,self.col)
        ch=self.peek(); line,col=self.line,self.col
        if ch=='$': return self.read_variable()
        if ch in ('"',"'"): return self.read_string(ch)
        if ch.isdigit() or (ch=='.' and self.peek(1).isdigit()): return self.read_number()
        if re.match(r'[A-Za-z_\x80-\xff]', ch): return self.read_identifier()
        for op in OPERATORS:
            if self.text.startswith(op, self.i):
                self.advance(len(op)); return Token(op, op, line, col)
        if ch in SINGLE:
            self.advance(); return Token(ch,ch,line,col)
        self.advance(); return Token(ch,ch,line,col)
    def tokenize(self):
        toks=[]
        while True:
            t=self.next_token(); toks.append(t)
            if t.type=='EOF': break
        return toks

# ----------------------------- AST Parser ------------------------------
def tok_desc(tok):
    if tok.type=='EOF': return "end of file"
    if tok.type in ('ID','VAR','NUMBER','STRING_D','STRING_S'): return f'"{tok.value}"' if tok.type=='ID' else tok.value
    return f'"{tok.value}"'

class Parser:
    def __init__(self, tokens):
        self.toks=tokens; self.pos=0
    def cur(self): return self.toks[self.pos]
    def peek(self, n=1):
        j=self.pos+n
        return self.toks[j] if j < len(self.toks) else self.toks[-1]
    def at(self, typ=None, val=None):
        t=self.cur()
        if typ is not None and t.type!=typ: return False
        if val is not None and str(t.value).lower()!=val.lower(): return False
        return True
    def at_id(self, val): return self.cur().type=='ID' and self.cur().value.lower()==val.lower()
    def advance(self):
        t=self.cur(); self.pos=min(self.pos+1, len(self.toks)-1); return t
    def accept(self, typ=None, val=None):
        if self.at(typ,val): return self.advance()
        return None
    def accept_id(self, val):
        if self.at_id(val): return self.advance()
        return None
    def expect(self, typ=None, val=None):
        if self.at(typ,val): return self.advance()
        t=self.cur()
        raise PHPParseError(f"syntax error, unexpected token {tok_desc(t)}", t.line)
    def expect_id(self, val):
        if self.at_id(val): return self.advance()
        t=self.cur(); raise PHPParseError(f"syntax error, unexpected token {tok_desc(t)}", t.line)

    def parse_program(self):
        stmts=[]
        while not self.at('EOF'):
            if self.accept(';'): continue
            stmts.append(self.parse_statement())
        return ('program', stmts)

    def parse_statement(self):
        t=self.cur()
        if self.accept('{'):
            stmts=[]
            while not self.at('}') and not self.at('EOF'):
                if self.accept(';'): continue
                stmts.append(self.parse_statement())
            self.expect('}')
            return ('block', stmts, t.line)
        if t.type=='ID':
            kw=t.value.lower()
            if kw=='echo': return self.parse_echo()
            if kw=='if': return self.parse_if()
            if kw=='while': return self.parse_while()
            if kw=='do': return self.parse_do()
            if kw=='for': return self.parse_for()
            if kw=='foreach': return self.parse_foreach()
            if kw=='function': return self.parse_function(False)
            if kw=='class': return self.parse_class()
            if kw=='return': return self.parse_return()
            if kw in ('break','continue'): return self.parse_break_continue(kw)
            if kw=='global': return self.parse_global()
            if kw=='static' and self.peek().type=='VAR': return self.parse_static_stmt()
            if kw=='unset': return self.parse_unset()
            if kw=='switch': return self.parse_switch()
            if kw in ('declare','namespace','use'):
                # Skip these declarations pragmatically.
                while not self.at(';') and not self.at('EOF') and not self.at('{'):
                    self.advance()
                if self.accept('{'):
                    depth=1
                    while depth and not self.at('EOF'):
                        if self.accept('{'): depth+=1
                        elif self.accept('}'): depth-=1
                        else: self.advance()
                else: self.accept(';')
                return ('empty', t.line)
        expr=self.parse_expression()
        self.accept(';')
        return ('exprstmt', expr, t.line)

    def parse_echo(self):
        t=self.advance()
        exprs=[]
        if self.at(';') or self.at('EOF') or self.at('}'):
            raise PHPParseError('syntax error, unexpected token ";"', self.cur().line)
        while True:
            exprs.append(self.parse_expression())
            if not self.accept(','): break
        self.accept(';')
        return ('echo', exprs, t.line)
    def parse_return(self):
        t=self.advance()
        expr=None
        if not self.at(';') and not self.at('EOF') and not self.at('}'):
            expr=self.parse_expression()
        self.accept(';')
        return ('return', expr, t.line)
    def parse_break_continue(self, kw):
        t=self.advance(); level=None
        if not self.at(';') and not self.at('EOF') and not self.at('}'):
            level=self.parse_expression()
        self.accept(';')
        return (kw, level, t.line)
    def parse_global(self):
        t=self.advance(); names=[]
        while True:
            v=self.expect('VAR'); names.append(v.value)
            if not self.accept(','): break
        self.accept(';')
        return ('global', names, t.line)
    def parse_static_stmt(self):
        t=self.advance(); items=[]
        while True:
            v=self.expect('VAR'); default=None
            if self.accept('='): default=self.parse_expression()
            items.append((v.value, default))
            if not self.accept(','): break
        self.accept(';')
        return ('staticstmt', items, t.line)
    def parse_unset(self):
        t=self.advance(); self.expect('('); items=[]
        if not self.at(')'):
            while True:
                items.append(self.parse_expression())
                if not self.accept(','): break
        self.expect(')'); self.accept(';')
        return ('unset', items, t.line)
    def parse_if(self):
        t=self.advance(); self.expect('('); cond=self.parse_expression(); self.expect(')')
        then=self.parse_statement()
        elifs=[]; els=None
        while self.at_id('elseif'):
            et=self.advance(); self.expect('('); ec=self.parse_expression(); self.expect(')'); eb=self.parse_statement(); elifs.append((ec,eb,et.line))
        if self.at_id('else'):
            self.advance(); els=self.parse_statement()
        return ('if', cond, then, elifs, els, t.line)
    def parse_while(self):
        t=self.advance(); self.expect('('); cond=self.parse_expression(); self.expect(')'); body=self.parse_statement()
        return ('while', cond, body, t.line)
    def parse_do(self):
        t=self.advance(); body=self.parse_statement(); self.expect_id('while'); self.expect('('); cond=self.parse_expression(); self.expect(')'); self.accept(';')
        return ('do', body, cond, t.line)
    def parse_for_expr_list(self, stop):
        arr=[]
        if self.at(stop): return arr
        while True:
            arr.append(self.parse_expression())
            if not self.accept(','): break
        return arr
    def parse_for(self):
        t=self.advance(); self.expect('(')
        init=self.parse_for_expr_list(';'); self.expect(';')
        cond=self.parse_for_expr_list(';'); self.expect(';')
        step=self.parse_for_expr_list(')'); self.expect(')')
        body=self.parse_statement()
        return ('for', init, cond, step, body, t.line)
    def parse_foreach(self):
        t=self.advance(); self.expect('('); arr=self.parse_expression(); self.expect_id('as')
        byref_val=False
        if self.accept('&'): byref_val=True
        first=self.parse_expression()
        key=None; val=first
        if self.accept('=>'):
            key=first
            if self.accept('&'): byref_val=True
            val=self.parse_expression()
        self.expect(')'); body=self.parse_statement()
        return ('foreach', arr, key, val, byref_val, body, t.line)
    def parse_function(self, anonymous=False):
        t=self.advance() if self.at_id('function') else self.cur()
        byref=False
        if self.accept('&'): byref=True
        name=None
        if not anonymous:
            name=self.expect('ID').value
        elif self.cur().type=='ID':
            name=self.advance().value
        self.expect('('); params=[]
        if not self.at(')'):
            while True:
                # Skip type hints/modifiers before parameter.
                p_byref=False; variadic=False
                while self.cur().type=='ID' and self.peek().type in ('ID','VAR','&','...','?'):
                    self.advance()
                if self.accept('?'):
                    if self.cur().type=='ID': self.advance()
                if self.accept('&'): p_byref=True
                if self.accept('...'): variadic=True
                var=self.expect('VAR').value
                default=None
                if self.accept('='): default=self.parse_expression()
                params.append((var, default, p_byref, variadic))
                if not self.accept(','): break
        self.expect(')')
        # Optional return type
        if self.accept(':'):
            while not self.at('{') and not self.at('EOF'):
                self.advance()
        self.expect('{'); body=[]
        while not self.at('}') and not self.at('EOF'):
            if self.accept(';'): continue
            body.append(self.parse_statement())
        self.expect('}')
        return ('function', name, params, ('block', body, t.line), byref, t.line)
    def parse_class(self):
        t=self.advance(); name=self.expect('ID').value
        # skip extends/implements clauses
        while not self.at('{') and not self.at('EOF'):
            self.advance()
        self.expect('{')
        members=[]
        while not self.at('}') and not self.at('EOF'):
            if self.accept(';'): continue
            mods=[]
            while self.cur().type=='ID' and self.cur().value.lower() in ('public','protected','private','static','final','abstract','readonly'):
                mods.append(self.advance().value.lower())
            if self.at_id('const'):
                self.advance()
                while True:
                    cname=self.expect('ID').value; self.expect('='); val=self.parse_expression(); members.append(('const', cname, val))
                    if not self.accept(','): break
                self.accept(';'); continue
            if self.at_id('var'):
                self.advance(); mods.append('public')
            if self.at_id('function'):
                fn=self.parse_function(anonymous=True)
                members.append(('method', mods, fn)); continue
            if self.cur().type=='VAR':
                v=self.advance().value; default=None
                if self.accept('='): default=self.parse_expression()
                members.append(('prop', mods, v, default))
                while self.accept(','):
                    v=self.expect('VAR').value; default=None
                    if self.accept('='): default=self.parse_expression()
                    members.append(('prop', mods, v, default))
                self.accept(';'); continue
