    # Expression grammar
    ASSIGN_OPS = {'=','+=','-=','*=','/=','%=','.=','&=','|=','^=','<<=','>>=','**=','??='}
    BIN_PREC = {
        'or':1, 'xor':2, 'and':3,
        '||':4, '&&':5, '|':6, '^':7, '&':8,
        '==':9, '!=':9, '<>':9, '===':9, '!==':9,
        '<':10, '>':10, '<=':10, '>=':10, '<=>':10, 'instanceof':10,
        '<<':11, '>>':11, '.':12, '+':13, '-':13,
        '*':14, '/':14, '%':14, '**':15,
    }
    RIGHT_ASSOC = {'**'}
    def parse_expression(self):
        return self.parse_assignment()
    def parse_assignment(self):
        left=self.parse_ternary()
        if self.cur().type in self.ASSIGN_OPS:
            op=self.advance().type
            right=self.parse_assignment()
            return ('assign', op, left, right, self.cur().line)
        return left
    def parse_ternary(self):
        cond=self.parse_coalesce()
        if self.accept('?'):
            iftrue=None
            if not self.at(':'):
