        t=self.cur()
        if t.type in self.BIN_PREC: return t.type
        if t.type=='ID' and t.value.lower() in self.BIN_PREC: return t.value.lower()
        return None
    def parse_binary(self, min_prec):
        left=self.parse_unary()
        while True:
            op=self.current_binop()
            if not op: break
            prec=self.BIN_PREC[op]
            if prec < min_prec: break
            self.advance()
            next_min=prec if op in self.RIGHT_ASSOC else prec+1
            right=self.parse_binary(next_min)
            left=('binary', op, left, right, self.cur().line)
        return left
    def parse_unary(self):
        t=self.cur()
