                    name=('varname', self.advance().value, t.line)
                elif self.cur().type=='ID':
                    name=('literal', self.advance().value, t.line)
                else:
                    raise PHPParseError(f"syntax error, unexpected token {tok_desc(self.cur())}", self.cur().line)
                expr=('static', expr, name, t.line)
            elif self.cur().type in ('++','--'):
