    def parse_primary(self):
        t=self.cur()
        if t.type=='NUMBER':
            self.advance(); s=t.value.replace('_','')
            try:
                if s.lower().startswith('0x'): val=int(s,16)
                elif s.lower().startswith('0b'): val=int(s,2)
                elif any(c in s.lower() for c in '.e'): val=float(s)
                else: val=int(s,10)
            except Exception:
                val=0
            return ('literal', val, t.line)
        if t.type in ('STRING_S','STRING_D'):
            self.advance(); return ('string', t.type, t.value, t.line)
        if t.type=='VAR':
            self.advance(); return ('var', t.value, t.line)
        if t.type=='ID':
            kw=t.value.lower()
            if kw in ('true','false','null'):
                self.advance(); return ('literal', True if kw=='true' else False if kw=='false' else None, t.line)
            if kw=='array':
                self.advance(); self.expect('('); elems=self.parse_array_elems(')'); self.expect(')'); return ('array', elems, t.line)
            if kw=='function':
                return self.parse_function(True)
            if kw in ('isset','empty'):
                self.advance(); self.expect('('); args=[]
                if not self.at(')'):
                    while True:
                        args.append(self.parse_expression())
                        if not self.accept(','): break
                self.expect(')'); return (kw, args, t.line)
            if kw in ('include','include_once','require','require_once'):
                self.advance(); expr=self.parse_expression(); return ('include', kw, expr, t.line)
            if kw in ('exit','die'):
                self.advance(); expr=None
                if self.accept('('):
                    if not self.at(')'): expr=self.parse_expression()
                    self.expect(')')
                elif not (self.at(';') or self.at('EOF') or self.at('}')):
                    expr=self.parse_expression()
                return ('exit', expr, t.line)
            if kw=='print':
                self.advance(); return ('print', self.parse_expression(), t.line)
            if kw=='new':
                self.advance(); cls=self.parse_primary()
                args=[]
                if self.accept('('):
                    if not self.at(')'):
                        while True:
                            args.append(self.parse_expression())
                            if not self.accept(','): break
                    self.expect(')')
                return ('new', cls, args, t.line)
            self.advance(); return ('name', t.value, t.line)
        if self.accept('['):
            elems=self.parse_array_elems(']'); self.expect(']'); return ('array', elems, t.line)
        if self.accept('('):
            expr=self.parse_expression(); self.expect(')'); return expr
        raise PHPParseError(f"syntax error, unexpected token {tok_desc(t)}", t.line)
    def parse_array_elems(self, end):
        elems=[]
        if self.at(end): return elems
        while not self.at(end) and not self.at('EOF'):
            if self.accept(','): continue
            byref=False
            if self.accept('&'): byref=True
            first=self.parse_expression()
            if self.accept('=>'):
                val=self.parse_expression(); elems.append((first,val,byref))
            else:
                elems.append((None,first,byref))
            if not self.accept(','): break
        return elems
