    return str(v)


def php_key_string(k):
    return str(k)


def loose_compare(a, b):
    # Return -1/0/1, following common PHP loose comparison behavior.
    if isinstance(a, bool) or isinstance(b, bool) or a is None or b is None:
        aa = php_bool(a); bb = php_bool(b)
        return (aa > bb) - (aa < bb)
    if isinstance(a, (int,float)) or isinstance(b, (int,float)):
        aa, af, _ = parse_numeric(a)
        bb, bf, _ = parse_numeric(b)
        return (aa > bb) - (aa < bb)
    if isinstance(a, str) and isinstance(b, str):
        ma = is_numeric_string(a); mb = is_numeric_string(b)
        if ma and mb:
            aa = parse_numeric(a)[0]; bb = parse_numeric(b)[0]
            return (aa > bb) - (aa < bb)
        return (a > b) - (a < b)
    if isinstance(a, PHPArray) and isinstance(b, PHPArray):
        return (len(a)>len(b)) - (len(a)<len(b)) if len(a)!=len(b) else 0
    return (php_string(a) > php_string(b)) - (php_string(a) < php_string(b))


def strict_equal(a,b):
    if type(a) is not type(b): return False
    if isinstance(a, PHPArray):
        return list(a.items()) == list(b.items())
    return a == b

# ------------------------------- Lexer --------------------------------
class Token:
    __slots__ = ('type','value','line','col')
    def __init__(self, typ, value, line, col):
        self.type=typ; self.value=value; self.line=line; self.col=col
    def __repr__(self):
        return f"Token({self.type!r},{self.value!r},{self.line}:{self.col})"

OPERATORS = [
    '===','!==','<<=','>>=','**=','...','??=','=>','->','::','++','--','==','!=','<>','<=','>=','&&','||','<<','>>','+=','-=','*=','/=','%=','.=','&=','|=','^=','??','**'
]
SINGLE = set('{}()[];,?:.+-*/%=<>!~&|^@')

class Lexer:
    def __init__(self, text, filename="Command line code", start_line=1):
        self.text=text; self.i=0; self.line=start_line; self.col=1; self.filename=filename; self.n=len(text)
    def peek(self, n=0):
        j=self.i+n
        return self.text[j] if j<self.n else ''
    def advance(self, count=1):
        s=''
        for _ in range(count):
            if self.i>=self.n: break
            ch=self.text[self.i]; s+=ch; self.i+=1
            if ch=='\n': self.line+=1; self.col=1
            else: self.col+=1
        return s
    def skip_ws_comments(self):
        while self.i<self.n:
            ch=self.peek()
            if ch in ' \t\r\n\v\f':
                self.advance(); continue
            if ch=='/' and self.peek(1)=='/':
                while self.i<self.n and self.peek()!='\n': self.advance()
                continue
            if ch=='#':
                while self.i<self.n and self.peek()!='\n': self.advance()
                continue
            if ch=='/' and self.peek(1)=='*':
                self.advance(2)
                while self.i<self.n and not (self.peek()=='*' and self.peek(1)=='/'):
                    self.advance()
                if self.i<self.n: self.advance(2)
                continue
            break
    def read_number(self):
        line,col=self.line,self.col; start=self.i
        if self.peek()=='0' and self.peek(1).lower() in ('x','b'):
            self.advance(2)
            while re.match(r'[0-9a-fA-F]', self.peek() or ''): self.advance()
            return Token('NUMBER', self.text[start:self.i], line, col)
        while self.peek().isdigit() or self.peek()=='_': self.advance()
        if self.peek()=='.' and self.peek(1).isdigit():
            self.advance()
            while self.peek().isdigit() or self.peek()=='_': self.advance()
        if self.peek().lower()=='e' and (self.peek(1).isdigit() or (self.peek(1) in '+-' and self.peek(2).isdigit())):
            self.advance()
            if self.peek() in '+-': self.advance()
            while self.peek().isdigit() or self.peek()=='_': self.advance()
        return Token('NUMBER', self.text[start:self.i], line, col)
    def read_identifier(self):
        line,col=self.line,self.col; start=self.i
        while re.match(r'[A-Za-z0-9_\\]', self.peek() or ''): self.advance()
        return Token('ID', self.text[start:self.i], line, col)
    def read_variable(self):
        line,col=self.line,self.col; self.advance()
        if self.peek()=='{':
            return Token('$', '$', line, col)
