# --------------------------- Formatting helpers -------------------------
def php_gettype(v):
    if v is None: return 'NULL'
    if isinstance(v,bool): return 'boolean'
    if isinstance(v,int): return 'integer'
    if isinstance(v,float): return 'double'
    if isinstance(v,str): return 'string'
    if isinstance(v,PHPArray): return 'array'
    if isinstance(v,PHPObject): return 'object'
    return 'unknown type'

def var_dump_str(v, indent=0, seen=None):
    if seen is None: seen=set()
    sp=' '*indent
    if v is None: return sp+'NULL\n'
    if isinstance(v,bool): return sp+('bool(true)' if v else 'bool(false)')+'\n'
    if isinstance(v,int) and not isinstance(v,bool): return sp+f'int({v})\n'
    if isinstance(v,float): return sp+f'float({format_float(v)})\n'
    if isinstance(v,str): return sp+f'string({len(v.encode("utf-8"))}) "{v}"\n'
    if isinstance(v,PHPArray):
        if id(v) in seen: return sp+'*RECURSION*\n'
        seen.add(id(v)); out=sp+f'array({len(v)}) {{\n'
        for k,val in v.items():
            key=f'[{k}]' if isinstance(k,int) else f'["{k}"]'
            out += sp+'  '+key+'=>\n'
            out += var_dump_str(val, indent+2, seen)
        out += sp+'}\n'; seen.discard(id(v)); return out
    if isinstance(v,PHPObject):
        out=sp+f'object({v.class_name})#{v.id} ({len(v.props)}) {{\n'
        for k,val in v.props.items():
            out += sp+f'  ["{k}"]=>\n' + var_dump_str(val, indent+2, seen)
        out += sp+'}\n'; return out
    return sp+repr(v)+'\n'

def print_r_str(v, indent=0):
    sp=' ' * indent
    if v is None: return ''
    if isinstance(v,bool): return '1' if v else ''
    if isinstance(v,(int,float)): return format_float(v) if isinstance(v,float) else str(v)
    if isinstance(v,str): return v
    if isinstance(v,PHPArray):
        out='Array\n'+sp+'(\n'
        for k,val in v.items():
            out += sp+f'    [{k}] => '
            if isinstance(val,(PHPArray,PHPObject)):
                out += print_r_str(val, indent+4)
            else:
                out += print_r_str(val,0)+'\n'
        out += sp+')\n'; return out
    if isinstance(v,PHPObject):
        out=f'{v.class_name} Object\n'+sp+'(\n'
        for k,val in v.props.items():
            out += sp+f'    [{k}] => '
            if isinstance(val,(PHPArray,PHPObject)): out += print_r_str(val, indent+4)
            else: out += print_r_str(val,0)+'\n'
        out += sp+')\n'; return out
    return str(v)

def var_export_str(v):
    if v is None: return 'NULL'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,(int,float)): return format_float(v) if isinstance(v,float) else str(v)
    if isinstance(v,str): return "'"+v.replace('\\','\\\\').replace("'","\\'")+"'"
    if isinstance(v,PHPArray):
        parts=[]
        for k,val in v.items(): parts.append(f"{var_export_str(k)} => {var_export_str(val)}")
        return 'array (\n  ' + ',\n  '.join(parts) + ',\n)' if parts else 'array (\n)'
    if isinstance(v,PHPObject): return f"(object) {var_export_str(PHPArray(list(v.props.items())))}"
    return repr(v)

def php_sprintf(args,line=None):
    if not args: return ''
    fmt=php_string(args[0]); vals=tuple((php_int(x) if isinstance(x,bool) else x) for x in args[1:])
    try:
        return fmt % vals
    except Exception:
        # A minimal sequential replacement fallback.
        it=iter(vals)
        def repl(m):
            try: v=next(it)
            except StopIteration: return m.group(0)
            typ=m.group(1)
            if typ in 'diu': return str(php_int(v))
            if typ in 'fFeEgG': return format_float(php_float(v))
            return php_string(v)
        return re.sub(r'%[-+ 0#\.\d]*(?:[bcdeEfFgGosuxX])', lambda m: repl((lambda:None)()), fmt)

def version_compare_builtin(args):
    if len(args)<2: return None
    def parts(v): return [int(x) if x.isdigit() else x for x in re.split(r'[.\-+_]', php_string(v))]
