def php_date(fmt, ts, utc=False):
    dt=datetime.datetime.utcfromtimestamp(ts) if utc else datetime.datetime.fromtimestamp(ts)
    repl={
        'Y':f'{dt.year:04d}','y':f'{dt.year%100:02d}','m':f'{dt.month:02d}','n':str(dt.month),'d':f'{dt.day:02d}','j':str(dt.day),
