        'U':str(int(ts)),'w':str((dt.weekday()+1)%7),'N':str(dt.isoweekday()),'M':dt.strftime('%b'),'F':dt.strftime('%B'),'D':dt.strftime('%a'),'l':dt.strftime('%A'),
        'a':'am' if dt.hour<12 else 'pm','A':'AM' if dt.hour<12 else 'PM','O':'+0000','P':'+00:00','T':'UTC','e':'UTC',
    }
    out=''; esc=False
    for ch in fmt:
        if esc: out+=ch; esc=False
        elif ch=='\\': esc=True
        else: out+=repl.get(ch,ch)
    return out
