    if typ=='literal': return node[1]
    if typ=='string': return eval_string(rt, node[1], node[2], env, node[3])
    if typ=='var': return env.get(node[1], node[2])
    if typ=='name':
        name=node[1]
        low=name.lower()
        if name in rt.constants: return rt.constants[name]
        # case-insensitive for true/null handled in parser; constants are case-sensitive now.
        if low=='self' or low=='static': return env.class_ctx or name
        if low=='parent': return name
