        if op=='||':
            left=eval_expr(rt,node[2],env); return php_bool(left) or php_bool(eval_expr(rt,node[3],env))
        if op=='and':
            left=eval_expr(rt,node[2],env); return php_bool(left) and php_bool(eval_expr(rt,node[3],env))
        if op=='or':
