    if typ=='ref': return eval_expr(rt,node[1],env)
    return None

MISSING=object()

def get_expr_silent(rt,node,env,missing_marker=False):
    try:
        if node[0]=='var':
            c=env.get_cell(node[1], False)
            if c is None: return MISSING if missing_marker else None
            return c.value
        if node[0]=='index':
            base=get_expr_silent(rt,node[1],env,missing_marker)
            if base is MISSING: return MISSING
            idx=eval_expr(rt,node[2],env) if node[2] is not None else None
            if isinstance(base,PHPArray):
                if base.exists(idx): return base.get(idx)
                return MISSING if missing_marker else None
            return MISSING if missing_marker else None
        if node[0]=='prop':
            obj=get_expr_silent(rt,node[1],env,missing_marker)
            if isinstance(obj,PHPObject):
                prop=php_string(eval_expr(rt,node[2],env))
                if prop in obj.props: return obj.props[prop]
            return MISSING if missing_marker else None
        return eval_expr(rt,node,env)
    except PHPExit: raise
    except Exception:
