def get_target(rt,node,env,warn=True):
    if node[0]=='var': return env.get(node[1], node[2], warn)
    if node[0]=='index': return read_index(rt, eval_expr(rt,node[1],env), eval_expr(rt,node[2],env) if node[2] is not None else None, node[3], warn=warn)
    if node[0]=='prop':
        obj=eval_expr(rt,node[1],env); prop=php_string(eval_expr(rt,node[2],env),rt,node[3])
        if isinstance(obj,PHPObject): return obj.props.get(prop, None)
        if warn: rt.warning('Attempt to read property "'+prop+'" on '+php_gettype(obj), node[3])
        return None
    if node[0]=='static':
        cls=class_name_from_node(rt,node[1],env); mem=php_string(eval_expr(rt,node[2],env),rt,node[3]); cd=rt.class_lookup(cls)
        if cd and mem in cd.static_props: return cd.static_props[mem].value
        return None
    return eval_expr(rt,node,env)

def assign_target(rt,node,env,value):
    if node[0]=='var': return env.set(node[1], value)
    if node[0]=='index':
        return assign_index(rt,node,env,value)
    if node[0]=='prop':
        obj=eval_expr(rt,node[1],env); prop=php_string(eval_expr(rt,node[2],env),rt,node[3])
        if not isinstance(obj,PHPObject):
            obj=PHPObject('stdClass')
            assign_target(rt,node[1],env,obj)
        obj.props[prop]=value; return value
    if node[0]=='static':
        cls=class_name_from_node(rt,node[1],env); mem=php_string(eval_expr(rt,node[2],env),rt,node[3]); cd=rt.class_lookup(cls)
        if cd is None:
            cd=ClassDef(cls); rt.define_class(cd)
        if mem not in cd.static_props: cd.static_props[mem]=Cell(None)
        cd.static_props[mem].value=value; return value
    rt.fatal('Cannot use temporary expression in write context', 'Error', node[-1] if isinstance(node[-1],int) else 1)

def assign_index(rt,node,env,value):
    base_node=node[1]; idx_node=node[2]; line=node[3]
    # Ensure base is an array for common assignment cases.
    base=get_target(rt,base_node,env,warn=False)
    if not isinstance(base,PHPArray):
        base=PHPArray(); assign_target(rt,base_node,env,base)
    if idx_node is None: base.append(value)
    else: base.set(eval_expr(rt,idx_node,env), value)
    return value

def unset_target(rt,node,env):
    if node[0]=='var':
        env.vars.pop(node[1], None); return
    if node[0]=='index':
        base=eval_expr(rt,node[1],env); idx=eval_expr(rt,node[2],env) if node[2] is not None else None
        if isinstance(base,PHPArray): base.delete(idx)

def read_index(rt, base, idx, line, warn=True):
    if isinstance(base, PHPArray):
        if base.exists(idx): return base.get(idx)
        if warn:
            key = idx if idx is not None else ''
            if isinstance(key,str): rt.warning(f'Undefined array key "{key}"', line)
            else: rt.warning(f'Undefined array key {key}', line)
        return None
    if isinstance(base, str):
        i=php_int(idx)
        if 0 <= i < len(base): return base[i]
        if warn: rt.warning(f'Uninitialized string offset {i}', line)
        return ''
    if base is None:
        if warn: rt.warning('Trying to access array offset on null', line)
        return None
    if warn: rt.warning('Trying to access array offset on value of type '+php_gettype(base), line)
    return None

def numeric_value(rt,v,line=None):
    val,isfloat,full=parse_numeric(v)
    if isinstance(v,str) and not full:
        if is_numeric_string(v): rt.warning('A non-numeric value encountered', line)
        else: rt.fatal('Unsupported operand types: string + int', 'TypeError', line)
    return val,isfloat

def apply_binary(rt,op,a,b,line=None):
    if op=='.': return php_string(a,rt,line)+php_string(b,rt,line)
    if op in ('+','-','*','/','%','**'):
        av,af=numeric_value(rt,a,line); bv,bf=numeric_value(rt,b,line)
        if op=='+': res=av+bv
        elif op=='-': res=av-bv
        elif op=='*': res=av*bv
        elif op=='/':
            if bv==0: rt.fatal('Division by zero','DivisionByZeroError',line)
            res=av/bv
            if float(res).is_integer() and not (af or bf): res=int(res)
            return res
        elif op=='%':
            if php_int(b)==0: rt.fatal('Modulo by zero','DivisionByZeroError',line)
            return php_int(a)%php_int(b)
        elif op=='**': res=av**bv
        if not (af or bf) and isinstance(res,float) and res.is_integer(): return int(res)
        if not (af or bf) and isinstance(res,int): return res
        return res
    if op in ('<<','>>','&','|','^'):
        aa=php_int(a); bb=php_int(b)
        return {'<<':aa<<bb,'>>':aa>>bb,'&':aa&bb,'|':aa|bb,'^':aa^bb}[op]
    if op in ('==','!=','<>','===','!==','<','>','<=','>=','<=>'):
        if op=='===': return strict_equal(a,b)
        if op=='!==': return not strict_equal(a,b)
        c=loose_compare(a,b)
        return {'==':c==0,'!=':c!=0,'<>':c!=0,'<':c<0,'>':c>0,'<=':c<=0,'>=':c>=0,'<=>':c}[op]
    if op=='xor': return php_bool(a) ^ php_bool(b)
    if op=='instanceof':
        cls = b if isinstance(b,str) else None
        return isinstance(a,PHPObject) and (cls is None or a.class_name.lower()==cls.lower())
    return None

def increment_value(v, delta):
    if isinstance(v,int): return v+delta
    if isinstance(v,float): return v+delta
    if isinstance(v,str):
        num, isf, full=parse_numeric(v)
        if full: return num+delta
        if delta>0:
            # PHP-ish alphabetic increment.
            if v=='': return '1'
            chars=list(v); i=len(chars)-1; carry=True
            while i>=0 and carry:
                c=chars[i]
                if c=='z': chars[i]='a'; carry=True
                elif c=='Z': chars[i]='A'; carry=True
                elif c=='9': chars[i]='0'; carry=True
                else: chars[i]=chr(ord(c)+1); carry=False
                i-=1
            if carry: chars.insert(0,'1' if v[-1].isdigit() else ('A' if v[-1].isupper() else 'a'))
            return ''.join(chars)
        return v
    return php_int(v)+delta

def eval_string(rt, typ, raw, env, line):
    if typ=='STRING_S':
        return raw.replace('\\\\','\\').replace("\\'","'")
    # Double-quoted escape processing with simple interpolation.
    out=''; i=0
    while i < len(raw):
        ch=raw[i]
        if ch=='\\' and i+1<len(raw):
            nxt=raw[i+1]; mp={'n':'\n','r':'\r','t':'\t','v':'\v','f':'\f','e':'\x1b','\\':'\\','"':'"','$':'$'}
            out += mp.get(nxt, nxt if nxt in '{}[]' else '\\'+nxt); i+=2; continue
        if ch=='$':
            m=re.match(r'\$([A-Za-z_][A-Za-z0-9_]*)', raw[i:])
            if m:
                name=m.group(1); val=env.get(name,line)
                j=i+len(m.group(0))
                # simple array offsets in strings: $a[key] / $a[0]
                if j < len(raw) and raw[j]=='[':
                    k=raw.find(']', j+1)
                    if k!=-1:
                        key=raw[j+1:k]
                        if (key.startswith('"') and key.endswith('"')) or (key.startswith("'") and key.endswith("'")): key=key[1:-1]
                        elif re.fullmatch(r'-?\d+', key): key=int(key)
                        val=read_index(rt,val,key,line)
                        j=k+1
                out += php_string(val,rt,line); i=j; continue
        out += ch; i+=1
    return out

def eval_call(rt,node,env):
    callee=node[1]; args=[]
    for a in node[2]:
        if isinstance(a,tuple) and a[0]=='splat':
            v=eval_expr(rt,a[1],env)
            if isinstance(v,PHPArray): args.extend(v.values())
        else: args.append(eval_expr(rt,a,env))
    line=node[3]
    # Function call, method call, static call.
    if callee[0]=='name':
        return call_function(rt, callee[1], args, node[2], env, line)
    if callee[0]=='var':
        fname=env.get(callee[1], line)
        return call_function(rt, php_string(fname,rt,line), args, node[2], env, line)
    if callee[0]=='prop':
        obj=eval_expr(rt,callee[1],env); method=php_string(eval_expr(rt,callee[2],env),rt,line)
        return call_method(rt,obj,method,args,node[2],env,line)
    if callee[0]=='static':
        cls=class_name_from_node(rt,callee[1],env); method=php_string(eval_expr(rt,callee[2],env),rt,line)
        return call_static_method(rt,cls,method,args,node[2],env,line)
    fn=eval_expr(rt,callee,env)
    if isinstance(fn,FunctionDef): return call_user_function(rt,fn,args,node[2],env,line)
    rt.fatal('Call to undefined function '+php_string(fn,rt,line)+'()','Error',line)

def call_function(rt,name,args,arg_nodes,env,line):
    low=str(name).lower()
    if low in rt.builtins:
        # Builtins get evaluated values. A few mutating functions are approximated.
        try:
            return rt.builtins[low](env,args,line)
        except PHPExit: raise
        except PHPFatal as e: rt.fatal(e.message,e.errtype,e.line or line)
        except Exception as e: rt.fatal(str(e),'Error',line)
    if low in rt.functions:
        return call_user_function(rt, rt.functions[low], args, arg_nodes, env, line)
    rt.fatal(f'Call to undefined function {name}()','Error',line)

def call_user_function(rt,fn,args,arg_nodes,caller_env,line,this_obj=None,class_ctx=None):
    newenv=Env(rt, parent=rt.global_env, function=fn, this_obj=this_obj, class_ctx=class_ctx)
    for i,(pname,default,byref,variadic) in enumerate(fn.params):
        if variadic:
            newenv.set(pname, PHPArray([(None,x) for x in args[i:]])); break
        if i < len(args):
            if byref and i < len(arg_nodes):
                cell=lvalue_cell(rt,arg_nodes[i],caller_env)
                if cell is not None: newenv.bind_cell(pname, cell)
                else: newenv.set(pname, args[i])
            else: newenv.set(pname, php_copy(args[i]))
        elif default is not None:
            newenv.set(pname, eval_expr(rt,default,caller_env))
        else:
            rt.fatal(f'Too few arguments to function {fn.name}()','ArgumentCountError',line)
    rt.call_stack.append(f'{rt.source_name}({line}): {fn.name}()')
    try:
        exec_stmt(rt, fn.body, newenv)
    except PHPReturn as r:
        return r.value
    finally:
        if rt.call_stack: rt.call_stack.pop()
    return None

def lvalue_cell(rt,node,env):
    if node[0]=='var': return env.get_cell(node[1], True)
    return None

def class_name_from_node(rt,node,env):
    if node[0]=='name':
        n=node[1]
        if n.lower() in ('self','static'): return env.class_ctx or n
        return n
    v=eval_expr(rt,node,env)
    if isinstance(v,PHPObject): return v.class_name
    return php_string(v,rt,node[-1] if isinstance(node[-1],int) else None)

def instantiate(rt,cls,args,line,env):
    cd=rt.class_lookup(cls)
    if cd is None:
        if cls.lower()=='stdclass': cd=ClassDef('stdClass'); rt.define_class(cd)
        else: rt.fatal(f'Class "{cls}" not found','Error',line)
    obj=PHPObject(cd.name)
    for k,v in cd.props.items(): obj.props[k]=php_copy(v)
    ctor=cd.methods.get('__construct')
    if ctor: call_user_function(rt,ctor,args,[],env,line,this_obj=obj,class_ctx=cd.name)
    return obj

def call_method(rt,obj,method,args,arg_nodes,env,line):
    if not isinstance(obj,PHPObject): rt.fatal(f'Call to a member function {method}() on {php_gettype(obj)}','Error',line)
    cd=rt.class_lookup(obj.class_name)
    fn=cd.methods.get(method.lower()) if cd else None
    if fn: return call_user_function(rt,fn,args,arg_nodes,env,line,this_obj=obj,class_ctx=cd.name)
    # Built-in DateTime-ish format method.
    if obj.class_name.lower() in ('datetime','datetimeimmutable') and method.lower()=='format':
        ts=obj.props.get('__timestamp', int(time.time()))
        return php_date(php_string(args[0] if args else '',rt,line), ts)
    rt.fatal(f'Call to undefined method {obj.class_name}::{method}()','Error',line)

def call_static_method(rt,cls,method,args,arg_nodes,env,line):
    cd=rt.class_lookup(cls); fn=cd.static_methods.get(method.lower()) if cd else None
    if fn: return call_user_function(rt,fn,args,arg_nodes,env,line,this_obj=None,class_ctx=cd.name)
    rt.fatal(f'Call to undefined method {cls}::{method}()','Error',line)

def include_file(rt,path,env,once=False,required=False,line=1):
    full=path if os.path.isabs(path) else os.path.join(os.getcwd(), path)
    if once and full in rt.included: return True
    try:
        with open(full,'r',encoding='utf-8',errors='replace') as f: content=f.read()
    except Exception:
        rt.warning(f'{"require" if required else "include"}({path}): Failed to open stream: No such file or directory', line)
        if required: rt.fatal(f'Failed opening required \'{path}\' (include_path=\'.:\')','Error',line)
        return False
    if once: rt.included.add(full)
    old_src,old_file=rt.source_name,rt.filename
    rt.source_name=full; rt.filename=full
    try:
        prog=parse_code(file_to_php_code(content), full)
        hoist(prog, rt, env)
        exec_stmt(rt, prog, env)
    except PHPReturn as r:
        return r.value
    finally:
        rt.source_name,rt.filename=old_src,old_file
    return True
