# ---------------------------- Evaluation --------------------------------
def eval_program(rt, program, env=None):
    env = env or rt.global_env
    hoist(program, rt, env)
    return exec_stmt(rt, program, env)

def hoist(node, rt, env):
    if not isinstance(node, tuple): return
    typ=node[0]
    if typ=='program' or typ=='block':
        for st in node[1]: hoist(st, rt, env)
    elif typ=='function' and node[1]:
        rt.define_function(FunctionDef(node[1], node[2], node[3], node[4]))
    elif typ=='class':
        define_class_from_ast(rt, env, node)

def define_class_from_ast(rt, env, node):
    _, name, members, line = node
    cd=ClassDef(name)
    for m in members:
        if m[0]=='const':
            cd.consts[m[1]]=eval_expr(rt, m[2], env)
        elif m[0]=='prop':
            mods=m[1]; default=eval_expr(rt, m[3], env) if m[3] is not None else None
            if 'static' in mods: cd.static_props[m[2]]=Cell(default)
            else: cd.props[m[2]]=default
        elif m[0]=='method':
            mods=m[1]; fnast=m[2]
            fn=FunctionDef(fnast[1], fnast[2], fnast[3], fnast[4])
            if 'static' in mods: cd.static_methods[(fn.name or '').lower()]=fn
            else: cd.methods[(fn.name or '').lower()]=fn
    rt.define_class(cd)

def exec_block(rt, stmts, env):
    for st in stmts:
        exec_stmt(rt, st, env)

def exec_stmt(rt, node, env):
    typ=node[0]
    if typ=='program': return exec_block(rt, node[1], env)
    if typ=='block': return exec_block(rt, node[1], env)
    if typ=='empty': return None
    if typ=='echo':
        for e in node[1]: rt.write(php_string(eval_expr(rt,e,env), rt, node[2]))
        return None
    if typ=='exprstmt': eval_expr(rt, node[1], env); return None
    if typ=='return': raise PHPReturn(eval_expr(rt,node[1],env) if node[1] is not None else None)
    if typ=='break': raise PHPBreak(php_int(eval_expr(rt,node[1],env)) if node[1] else 1)
    if typ=='continue': raise PHPContinue(php_int(eval_expr(rt,node[1],env)) if node[1] else 1)
    if typ=='global':
        for name in node[1]: env.bind_cell(name, rt.global_env.get_cell(name, True))
        return None
    if typ=='staticstmt':
        fn=env.function
        for name, default in node[1]:
            if fn is not None:
                if name not in fn.static_cells:
                    fn.static_cells[name]=Cell(eval_expr(rt, default, env) if default is not None else None)
                env.bind_cell(name, fn.static_cells[name])
            else:
                if env.get_cell(name) is None: env.set(name, eval_expr(rt, default, env) if default is not None else None)
        return None
    if typ=='unset':
        for e in node[1]: unset_target(rt,e,env)
        return None
    if typ=='function':
        if node[1]: rt.define_function(FunctionDef(node[1], node[2], node[3], node[4]))
        return None
    if typ=='class':
        define_class_from_ast(rt, env, node); return None
    if typ=='if':
        if php_bool(eval_expr(rt,node[1],env)): return exec_stmt(rt,node[2],env)
        for cond,body,line in node[3]:
            if php_bool(eval_expr(rt,cond,env)): return exec_stmt(rt,body,env)
        if node[4] is not None: return exec_stmt(rt,node[4],env)
        return None
    if typ=='while':
        while php_bool(eval_expr(rt,node[1],env)):
            try: exec_stmt(rt,node[2],env)
            except PHPContinue as c:
                if c.levels>1: c.levels-=1; raise
            except PHPBreak as b:
                if b.levels>1: b.levels-=1; raise
                break
        return None
    if typ=='do':
        while True:
            try: exec_stmt(rt,node[1],env)
            except PHPContinue as c:
                if c.levels>1: c.levels-=1; raise
            except PHPBreak as b:
                if b.levels>1: b.levels-=1; raise
                break
            if not php_bool(eval_expr(rt,node[2],env)): break
        return None
    if typ=='for':
        for e in node[1]: eval_expr(rt,e,env)
        while True:
            ok=True
            if node[2]: ok=php_bool(eval_expr(rt,node[2][-1],env))
            if not ok: break
            try: exec_stmt(rt,node[4],env)
            except PHPContinue as c:
                if c.levels>1: c.levels-=1; raise
            except PHPBreak as b:
                if b.levels>1: b.levels-=1; raise
                break
            for e in node[3]: eval_expr(rt,e,env)
        return None
    if typ=='foreach':
        arr=eval_expr(rt,node[1],env)
        if isinstance(arr, PHPArray): items=list(arr.items())
        elif isinstance(arr, PHPObject): items=list(arr.props.items())
        else: items=[]
        for k,v in items:
            if node[2] is not None: assign_target(rt,node[2],env,k)
            assign_target(rt,node[3],env,v)
            try: exec_stmt(rt,node[5],env)
            except PHPContinue as c:
                if c.levels>1: c.levels-=1; raise
            except PHPBreak as b:
                if b.levels>1: b.levels-=1; raise
                break
        return None
    if typ=='switch':
        val=eval_expr(rt,node[1],env); run=False
        for case,stmts in node[2]:
            if case is None or run or loose_compare(val, eval_expr(rt,case,env))==0:
                run=True
                try: exec_block(rt,stmts,env)
                except PHPBreak as b:
                    if b.levels>1: b.levels-=1; raise
                    break
        return None
    return None

def eval_expr(rt, node, env):
    typ=node[0]
    if typ=='literal': return node[1]
    if typ=='string': return eval_string(rt, node[1], node[2], env, node[3])
    if typ=='var': return env.get(node[1], node[2])
    if typ=='name':
        name=node[1]
        low=name.lower()
        if name in rt.constants: return rt.constants[name]
        # case-insensitive for true/null handled in parser; constants are case-sensitive now.
        if low=='self' or low=='static': return env.class_ctx or name
        if low=='parent': return name
        rt.fatal(f'Undefined constant "{name}"', 'Error', node[2])
    if typ=='varname': return env.get(node[1], node[2])
    if typ=='array':
        arr=PHPArray()
        for kexpr,vexpr,byref in node[1]:
            val=eval_expr(rt,vexpr,env)
            if kexpr is None: arr.append(val)
            else: arr.set(eval_expr(rt,kexpr,env), val)
        return arr
    if typ=='assign':
        op=node[1]
        if op=='=':
            val=eval_expr(rt,node[3],env); return assign_target(rt,node[2],env,val)
        if op=='??=':
            cur=get_target(rt,node[2],env,warn=False)
            if cur is None:
                val=eval_expr(rt,node[3],env); return assign_target(rt,node[2],env,val)
            return cur
        cur=get_target(rt,node[2],env,warn=True); rhs=eval_expr(rt,node[3],env)
        val=apply_binary(rt, op[:-1] if op!='.=' else '.', cur, rhs, node[4])
        return assign_target(rt,node[2],env,val)
    if typ=='binary':
        op=node[1]
        if op=='&&':
            left=eval_expr(rt,node[2],env); return php_bool(left) and php_bool(eval_expr(rt,node[3],env))
        if op=='||':
            left=eval_expr(rt,node[2],env); return php_bool(left) or php_bool(eval_expr(rt,node[3],env))
        if op=='and':
            left=eval_expr(rt,node[2],env); return php_bool(left) and php_bool(eval_expr(rt,node[3],env))
        if op=='or':
            left=eval_expr(rt,node[2],env); return php_bool(left) or php_bool(eval_expr(rt,node[3],env))
        if op=='??':
            left=get_expr_silent(rt,node[2],env)
            return left if left is not None else eval_expr(rt,node[3],env)
        return apply_binary(rt,op,eval_expr(rt,node[2],env),eval_expr(rt,node[3],env),node[4])
    if typ=='unary':
        op=node[1]
        if op=='@':
            old=rt.ini.get('error_reporting'); rt.ini['error_reporting']='0'
            try: return eval_expr(rt,node[2],env)
            finally: rt.ini['error_reporting']=old
        if op=='!': return not php_bool(eval_expr(rt,node[2],env))
        if op=='+': return numeric_value(rt, eval_expr(rt,node[2],env), node[3])[0]
        if op=='-':
            v=numeric_value(rt, eval_expr(rt,node[2],env), node[3])[0]; return -v
        if op=='~': return ~php_int(eval_expr(rt,node[2],env))
        if op in ('++','--'):
            cur=get_target(rt,node[2],env); new=increment_value(cur, 1 if op=='++' else -1); assign_target(rt,node[2],env,new); return new
    if typ=='postfix':
        cur=get_target(rt,node[2],env); new=increment_value(cur, 1 if node[1]=='++' else -1); assign_target(rt,node[2],env,new); return cur
    if typ=='cast':
        v=eval_expr(rt,node[2],env); c=node[1]
        if c in ('int','integer'): return php_int(v)
        if c in ('bool','boolean'): return php_bool(v)
        if c in ('float','double','real'): return php_float(v)
        if c=='string': return php_string(v,rt,node[3])
        if c=='array':
            if isinstance(v,PHPArray): return v
            return PHPArray([(None,v)]) if v is not None else PHPArray()
        if c=='object':
            if isinstance(v,PHPObject): return v
            o=PHPObject('stdClass')
            if isinstance(v,PHPArray): o.props=OrderedDict((str(k),val) for k,val in v.items())
            else: o.props['scalar']=v
            return o
        return None
    if typ=='ternary':
        cond=eval_expr(rt,node[1],env)
        if php_bool(cond): return cond if node[2] is None else eval_expr(rt,node[2],env)
        return eval_expr(rt,node[3],env)
    if typ=='index':
        return read_index(rt, eval_expr(rt,node[1],env), eval_expr(rt,node[2],env) if node[2] is not None else None, node[3])
    if typ=='prop':
        obj=eval_expr(rt,node[1],env); prop=php_string(eval_expr(rt,node[2],env),rt,node[3])
        if isinstance(obj,PHPObject): return obj.props.get(prop, None)
        rt.warning('Attempt to read property "'+prop+'" on '+php_gettype(obj), node[3]); return None
    if typ=='static':
        cls=class_name_from_node(rt,node[1],env); mem=php_string(eval_expr(rt,node[2],env),rt,node[3])
        cd=rt.class_lookup(cls)
        if cd:
            if mem in cd.consts: return cd.consts[mem]
            if mem in cd.static_props: return cd.static_props[mem].value
        rt.fatal(f'Undefined constant {cls}::{mem}', 'Error', node[3])
    if typ=='call':
        return eval_call(rt,node,env)
    if typ=='print':
        rt.write(php_string(eval_expr(rt,node[1],env),rt,node[2])); return 1
    if typ=='isset':
        for arg in node[1]:
            val=get_expr_silent(rt,arg,env, missing_marker=True)
            if val is MISSING or val is None: return False
        return True
    if typ=='empty':
        val=get_expr_silent(rt,node[1][0],env, missing_marker=True) if node[1] else None
        return True if val is MISSING else (not php_bool(val))
    if typ=='exit':
        code=0
        if node[1] is not None:
            v=eval_expr(rt,node[1],env)
            if isinstance(v,str): rt.write(v); code=0
            else: code=php_int(v)
        raise PHPExit(code)
    if typ=='include':
        path=php_string(eval_expr(rt,node[2],env),rt,node[3])
        return include_file(rt, path, env, once=('once' in node[1]), required=('require' in node[1]), line=node[3])
    if typ=='new':
        cls=class_name_from_node(rt,node[1],env); return instantiate(rt, cls, [eval_expr(rt,a,env) for a in node[2]], node[3], env)
    if typ=='function':
        return FunctionDef(node[1] or '{closure}', node[2], node[3], node[4], env)
    if typ=='ref': return eval_expr(rt,node[1],env)
    return None

MISSING=object()

def get_expr_silent(rt,node,env,missing_marker=False):
    try:
        if node[0]=='var':
            c=env.get_cell(node[1], False)
            if c is None: return MISSING if missing_marker else None
            return c.value
        if node[0]=='index':
            base=get_expr_silent(rt,node[1],env,missing_marker)
            if base is MISSING: return MISSING
            idx=eval_expr(rt,node[2],env) if node[2] is not None else None
            if isinstance(base,PHPArray):
                if base.exists(idx): return base.get(idx)
                return MISSING if missing_marker else None
            return MISSING if missing_marker else None
        if node[0]=='prop':
            obj=get_expr_silent(rt,node[1],env,missing_marker)
            if isinstance(obj,PHPObject):
                prop=php_string(eval_expr(rt,node[2],env))
                if prop in obj.props: return obj.props[prop]
            return MISSING if missing_marker else None
        return eval_expr(rt,node,env)
    except PHPExit: raise
    except Exception:
        return MISSING if missing_marker else None

def get_target(rt,node,env,warn=True):
    if node[0]=='var': return env.get(node[1], node[2], warn)
    if node[0]=='index': return read_index(rt, eval_expr(rt,node[1],env), eval_expr(rt,node[2],env) if node[2] is not None else None, node[3], warn=warn)
    if node[0]=='prop':
        obj=eval_expr(rt,node[1],env); prop=php_string(eval_expr(rt,node[2],env),rt,node[3])
        if isinstance(obj,PHPObject): return obj.props.get(prop, None)
        if warn: rt.warning('Attempt to read property "'+prop+'" on '+php_gettype(obj), node[3])
        return None
    if node[0]=='static':
        cls=class_name_from_node(rt,node[1],env); mem=php_string(eval_expr(rt,node[2],env),rt,node[3]); cd=rt.class_lookup(cls)
        if cd and mem in cd.static_props: return cd.static_props[mem].value
        return None
    return eval_expr(rt,node,env)

def assign_target(rt,node,env,value):
    if node[0]=='var': return env.set(node[1], value)
    if node[0]=='index':
        return assign_index(rt,node,env,value)
    if node[0]=='prop':
        obj=eval_expr(rt,node[1],env); prop=php_string(eval_expr(rt,node[2],env),rt,node[3])
        if not isinstance(obj,PHPObject):
            obj=PHPObject('stdClass')
            assign_target(rt,node[1],env,obj)
        obj.props[prop]=value; return value
    if node[0]=='static':
        cls=class_name_from_node(rt,node[1],env); mem=php_string(eval_expr(rt,node[2],env),rt,node[3]); cd=rt.class_lookup(cls)
        if cd is None:
            cd=ClassDef(cls); rt.define_class(cd)
        if mem not in cd.static_props: cd.static_props[mem]=Cell(None)
        cd.static_props[mem].value=value; return value
    rt.fatal('Cannot use temporary expression in write context', 'Error', node[-1] if isinstance(node[-1],int) else 1)

def assign_index(rt,node,env,value):
    base_node=node[1]; idx_node=node[2]; line=node[3]
    # Ensure base is an array for common assignment cases.
    base=get_target(rt,base_node,env,warn=False)
    if not isinstance(base,PHPArray):
        base=PHPArray(); assign_target(rt,base_node,env,base)
    if idx_node is None: base.append(value)
    else: base.set(eval_expr(rt,idx_node,env), value)
    return value

def unset_target(rt,node,env):
    if node[0]=='var':
        env.vars.pop(node[1], None); return
    if node[0]=='index':
        base=eval_expr(rt,node[1],env); idx=eval_expr(rt,node[2],env) if node[2] is not None else None
        if isinstance(base,PHPArray): base.delete(idx)

def read_index(rt, base, idx, line, warn=True):
    if isinstance(base, PHPArray):
        if base.exists(idx): return base.get(idx)
        if warn:
            key = idx if idx is not None else ''
            if isinstance(key,str): rt.warning(f'Undefined array key "{key}"', line)
            else: rt.warning(f'Undefined array key {key}', line)
        return None
    if isinstance(base, str):
        i=php_int(idx)
        if 0 <= i < len(base): return base[i]
        if warn: rt.warning(f'Uninitialized string offset {i}', line)
        return ''
    if base is None:
        if warn: rt.warning('Trying to access array offset on null', line)
        return None
    if warn: rt.warning('Trying to access array offset on value of type '+php_gettype(base), line)
    return None

def numeric_value(rt,v,line=None):
    val,isfloat,full=parse_numeric(v)
    if isinstance(v,str) and not full:
        if is_numeric_string(v): rt.warning('A non-numeric value encountered', line)
        else: rt.fatal('Unsupported operand types: string + int', 'TypeError', line)
    return val,isfloat

def apply_binary(rt,op,a,b,line=None):
    if op=='.': return php_string(a,rt,line)+php_string(b,rt,line)
    if op in ('+','-','*','/','%','**'):
        av,af=numeric_value(rt,a,line); bv,bf=numeric_value(rt,b,line)
        if op=='+': res=av+bv
        elif op=='-': res=av-bv
        elif op=='*': res=av*bv
        elif op=='/':
            if bv==0: rt.fatal('Division by zero','DivisionByZeroError',line)
            res=av/bv
            if float(res).is_integer() and not (af or bf): res=int(res)
            return res
        elif op=='%':
            if php_int(b)==0: rt.fatal('Modulo by zero','DivisionByZeroError',line)
            return php_int(a)%php_int(b)
        elif op=='**': res=av**bv
        if not (af or bf) and isinstance(res,float) and res.is_integer(): return int(res)
        if not (af or bf) and isinstance(res,int): return res
        return res
    if op in ('<<','>>','&','|','^'):
        aa=php_int(a); bb=php_int(b)
        return {'<<':aa<<bb,'>>':aa>>bb,'&':aa&bb,'|':aa|bb,'^':aa^bb}[op]
    if op in ('==','!=','<>','===','!==','<','>','<=','>=','<=>'):
        if op=='===': return strict_equal(a,b)
        if op=='!==': return not strict_equal(a,b)
        c=loose_compare(a,b)
        return {'==':c==0,'!=':c!=0,'<>':c!=0,'<':c<0,'>':c>0,'<=':c<=0,'>=':c>=0,'<=>':c}[op]
    if op=='xor': return php_bool(a) ^ php_bool(b)
    if op=='instanceof':
        cls = b if isinstance(b,str) else None
        return isinstance(a,PHPObject) and (cls is None or a.class_name.lower()==cls.lower())
    return None

def increment_value(v, delta):
    if isinstance(v,int): return v+delta
    if isinstance(v,float): return v+delta
    if isinstance(v,str):
        num, isf, full=parse_numeric(v)
        if full: return num+delta
        if delta>0:
            # PHP-ish alphabetic increment.
            if v=='': return '1'
            chars=list(v); i=len(chars)-1; carry=True
            while i>=0 and carry:
                c=chars[i]
                if c=='z': chars[i]='a'; carry=True
                elif c=='Z': chars[i]='A'; carry=True
                elif c=='9': chars[i]='0'; carry=True
                else: chars[i]=chr(ord(c)+1); carry=False
                i-=1
            if carry: chars.insert(0,'1' if v[-1].isdigit() else ('A' if v[-1].isupper() else 'a'))
            return ''.join(chars)
        return v
    return php_int(v)+delta

def eval_string(rt, typ, raw, env, line):
    if typ=='STRING_S':
        return raw.replace('\\\\','\\').replace("\\'","'")
    # Double-quoted escape processing with simple interpolation.
    out=''; i=0
    while i < len(raw):
        ch=raw[i]
        if ch=='\\' and i+1<len(raw):
            nxt=raw[i+1]; mp={'n':'\n','r':'\r','t':'\t','v':'\v','f':'\f','e':'\x1b','\\':'\\','"':'"','$':'$'}
            out += mp.get(nxt, nxt if nxt in '{}[]' else '\\'+nxt); i+=2; continue
        if ch=='$':
            m=re.match(r'\$([A-Za-z_][A-Za-z0-9_]*)', raw[i:])
            if m:
                name=m.group(1); val=env.get(name,line)
                j=i+len(m.group(0))
                # simple array offsets in strings: $a[key] / $a[0]
                if j < len(raw) and raw[j]=='[':
                    k=raw.find(']', j+1)
                    if k!=-1:
                        key=raw[j+1:k]
                        if (key.startswith('"') and key.endswith('"')) or (key.startswith("'") and key.endswith("'")): key=key[1:-1]
                        elif re.fullmatch(r'-?\d+', key): key=int(key)
                        val=read_index(rt,val,key,line)
                        j=k+1
                out += php_string(val,rt,line); i=j; continue
        out += ch; i+=1
    return out

def eval_call(rt,node,env):
    callee=node[1]; args=[]
    for a in node[2]:
        if isinstance(a,tuple) and a[0]=='splat':
            v=eval_expr(rt,a[1],env)
            if isinstance(v,PHPArray): args.extend(v.values())
        else: args.append(eval_expr(rt,a,env))
    line=node[3]
    # Function call, method call, static call.
    if callee[0]=='name':
        return call_function(rt, callee[1], args, node[2], env, line)
    if callee[0]=='var':
        fname=env.get(callee[1], line)
        return call_function(rt, php_string(fname,rt,line), args, node[2], env, line)
    if callee[0]=='prop':
        obj=eval_expr(rt,callee[1],env); method=php_string(eval_expr(rt,callee[2],env),rt,line)
        return call_method(rt,obj,method,args,node[2],env,line)
    if callee[0]=='static':
        cls=class_name_from_node(rt,callee[1],env); method=php_string(eval_expr(rt,callee[2],env),rt,line)
        return call_static_method(rt,cls,method,args,node[2],env,line)
    fn=eval_expr(rt,callee,env)
    if isinstance(fn,FunctionDef): return call_user_function(rt,fn,args,node[2],env,line)
    rt.fatal('Call to undefined function '+php_string(fn,rt,line)+'()','Error',line)

def call_function(rt,name,args,arg_nodes,env,line):
    low=str(name).lower()
    if low in rt.builtins:
        # Builtins get evaluated values. A few mutating functions are approximated.
        try:
            return rt.builtins[low](env,args,line)
        except PHPExit: raise
        except PHPFatal as e: rt.fatal(e.message,e.errtype,e.line or line)
        except Exception as e: rt.fatal(str(e),'Error',line)
    if low in rt.functions:
        return call_user_function(rt, rt.functions[low], args, arg_nodes, env, line)
    rt.fatal(f'Call to undefined function {name}()','Error',line)

def call_user_function(rt,fn,args,arg_nodes,caller_env,line,this_obj=None,class_ctx=None):
    newenv=Env(rt, parent=rt.global_env, function=fn, this_obj=this_obj, class_ctx=class_ctx)
    for i,(pname,default,byref,variadic) in enumerate(fn.params):
        if variadic:
            newenv.set(pname, PHPArray([(None,x) for x in args[i:]])); break
        if i < len(args):
            if byref and i < len(arg_nodes):
                cell=lvalue_cell(rt,arg_nodes[i],caller_env)
                if cell is not None: newenv.bind_cell(pname, cell)
                else: newenv.set(pname, args[i])
            else: newenv.set(pname, php_copy(args[i]))
        elif default is not None:
            newenv.set(pname, eval_expr(rt,default,caller_env))
        else:
            rt.fatal(f'Too few arguments to function {fn.name}()','ArgumentCountError',line)
    rt.call_stack.append(f'{rt.source_name}({line}): {fn.name}()')
    try:
        exec_stmt(rt, fn.body, newenv)
    except PHPReturn as r:
        return r.value
    finally:
        if rt.call_stack: rt.call_stack.pop()
    return None

def lvalue_cell(rt,node,env):
    if node[0]=='var': return env.get_cell(node[1], True)
    return None

def class_name_from_node(rt,node,env):
    if node[0]=='name':
        n=node[1]
        if n.lower() in ('self','static'): return env.class_ctx or n
        return n
    v=eval_expr(rt,node,env)
    if isinstance(v,PHPObject): return v.class_name
    return php_string(v,rt,node[-1] if isinstance(node[-1],int) else None)

def instantiate(rt,cls,args,line,env):
    cd=rt.class_lookup(cls)
    if cd is None:
        if cls.lower()=='stdclass': cd=ClassDef('stdClass'); rt.define_class(cd)
        else: rt.fatal(f'Class "{cls}" not found','Error',line)
