def parse_code(code, filename="Command line code"):
    toks=Lexer(code, filename).tokenize()
    return Parser(toks).parse_program()

def run_code(rt, code, filename="Command line code", env=None, is_file=False):
    try:
        phpcode=file_to_php_code(code) if is_file else code
        prog=parse_code(phpcode, filename)
        return eval_program(rt, prog, env or rt.global_env)
    except PHPParseError as e:
        rt.write(f"\nParse error: {e.message} in {filename} on line {e.line}\n")
        raise PHPExit(255)
    except PHPFatal as e:
        rt.fatal(e.message, e.errtype, e.line)

def lint_code(code, filename="Standard input code", is_file=True):
    try:
        parse_code(file_to_php_code(code) if is_file else code, filename)
        sys.stdout.write(f"No syntax errors detected in {filename}\n")
        return 0
    except PHPParseError as e:
        sys.stdout.write(f"\nParse error: {e.message} in {filename} on line {e.line}\n")
        sys.stdout.write(f"Errors parsing {filename}\n")
        return 255

def strip_comments_whitespace(content):
    # A pragmatic approximation of php -w: remove comments and squeeze blanks.
    code=file_to_php_code(content)
    code=re.sub(r'/\*.*?\*/','',code,flags=re.S)
    code=re.sub(r'//[^\n]*','',code)
    code=re.sub(r'#[^\n]*','',code)
    code=re.sub(r'\s+',' ',code).strip()
    return code+'\n'

def highlight_file(content):
    # Simple HTML source presentation; colors match the documented defaults.
    return '<pre><code style="color: #000000">' + html.escape(content) + '\n</code></pre>\n'

