# ------------------------------- CLI ------------------------------------
class CLIConfig:
    def __init__(self):
        self.ini={}; self.mode=None; self.code=None; self.file=None; self.args=[]; self.lint=False; self.highlight=False; self.strip=False
        self.begin=None; self.process_code=None; self.process_file=None; self.end=None; self.repeat=1; self.docroot='.'; self.server=None; self.router=None

def option_error(msg):
    sys.stderr.write(msg+'\n'); sys.stdout.write(HELP_TEXT); return 1

def parse_cli(argv):
    cfg=CLIConfig(); i=0; endopts=False
    while i < len(argv):
        a=argv[i]
        if endopts:
            if cfg.file is None and cfg.mode is None:
                # With -- and no mode, PHP reads stdin; remaining are script args.
                cfg.args=argv[i:]; break
            else:
                cfg.args=argv[i:]; break
        if a=='--': endopts=True; i+=1; continue
        if a in ('-h','--help','-?'):
            cfg.mode='help'; return cfg
        if a in ('-v','--version'):
            cfg.mode='version'; return cfg
        if a in ('-m','--modules'):
            cfg.mode='modules'; return cfg
        if a in ('-i','--info'):
            cfg.mode='info'; return cfg
        if a=='--ini': cfg.mode='ini'; return cfg
        if a=='--ini=diff': cfg.mode='ini_diff'; return cfg
        if a in ('-l','--syntax-check'):
            cfg.lint=True; i+=1; continue
        if a in ('-s','--syntax-highlight'):
            cfg.highlight=True; i+=1; continue
        if a=='-w': cfg.strip=True; i+=1; continue
        if a in ('-a','--interactive'):
            cfg.mode='interactive'; return cfg
        if a in ('-n','--no-php-ini','-e','-H'):
            i+=1; continue
        if a in ('-c','-d','-f','-r','-B','-R','-F','-E','-S','-t','--rf','--rc','--re','--rz','--ri','--repeat'):
            if i+1>=len(argv):
                ch=a[1] if a.startswith('-') else '-'
                return ('error', f"Error in argument {i+1}, char 2: no argument for option {ch}")
            val=argv[i+1]; i+=2
            if a=='-c': continue
            if a=='-d':
                if '=' in val: k,v=val.split('=',1)
                else: k,v=val,'1'
                if k=='display_errors' and v.lower()=='stderr': cfg.ini[k]='stderr'
                else: cfg.ini[k]=v
                continue
            if a=='-f': cfg.file=val; continue
            if a=='-r': cfg.mode='run_code'; cfg.code=val; continue
            if a=='-B': cfg.begin=val; continue
            if a=='-R': cfg.mode='process'; cfg.process_code=val; continue
            if a=='-F': cfg.mode='process'; cfg.process_file=val; continue
            if a=='-E': cfg.end=val; continue
            if a=='-S': cfg.mode='server'; cfg.server=val; continue
            if a=='-t': cfg.docroot=val; continue
            if a=='--repeat': cfg.repeat=max(1,int(val)); continue
            if a in ('--rf','--rc','--re','--rz','--ri'):
                cfg.mode=a[2:]; cfg.code=val; return cfg
        elif a.startswith('-d') and len(a)>2:
            val=a[2:]; k,v=(val.split('=',1)+['1'])[:2] if '=' in val else (val,'1'); cfg.ini[k]=v; i+=1; continue
        elif a.startswith('-'):
            if a.startswith('--'):
                return ('error', f"Error in argument {i+1}, char 1: no argument for option -")
            return ('error', f"Error in argument {i+1}, char 2: option not found {a[1:2]}")
        else:
            cfg.file=a; cfg.args=argv[i+1:]; break
    return cfg

def run_server(cfg):
    # Minimal development server: enough to start and serve static/router requests.
    import http.server, socketserver
    host,port = cfg.server.rsplit(':',1) if ':' in cfg.server else ('127.0.0.1',cfg.server)
    port=int(port)
    os.chdir(cfg.docroot)
    class Handler(http.server.SimpleHTTPRequestHandler):
        server_version=f"PHP {VERSION} Development Server"
        def log_message(self, fmt, *args): sys.stderr.write("[%s] %s\n"%(time.strftime('%a %b %e %H:%M:%S %Y'), fmt%args))
    with socketserver.TCPServer((host,port), Handler) as httpd:
        actual=httpd.server_address[1]
        sys.stderr.write(f"[{time.strftime('%a %b %e %H:%M:%S %Y')}] PHP {VERSION} Development Server (http://{host}:{actual}) started\n"); sys.stderr.flush()
        httpd.serve_forever()

def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    parsed=parse_cli(argv)
    if isinstance(parsed, tuple) and parsed[0]=='error': return option_error(parsed[1])
    cfg=parsed
    try:
        if cfg.mode=='help': sys.stdout.write(HELP_TEXT); return 0
        if cfg.mode=='version': sys.stdout.write(VERSION_TEXT); return 0
        if cfg.mode=='modules': sys.stdout.write(MODULES_TEXT); return 0
        if cfg.mode=='ini': sys.stdout.write(INI_TEXT); return 0
        if cfg.mode=='ini_diff': sys.stdout.write(INI_DIFF_TEXT); return 0
        if cfg.mode=='info': sys.stdout.write(phpinfo_text()); return 0
        if cfg.mode=='interactive': sys.stdout.write('Interactive shell (-a) requires the readline extension.\n'); return 1
        if cfg.mode=='rf':
            s=reflection_function(cfg.code)
            if s is None: sys.stdout.write(f"Exception: Function {cfg.code}() does not exist\n"); return 1
            sys.stdout.write(s); return 0
        if cfg.mode=='rc':
            s=reflection_class(cfg.code)
            if s is None: sys.stdout.write(f"Exception: Class \"{cfg.code}\" does not exist\n"); return 1
            sys.stdout.write(s); return 0
        if cfg.mode=='re':
            s=extension_info(cfg.code)
            if s is None: sys.stdout.write(f"Exception: Extension \"{cfg.code}\" does not exist\n"); return 1
            sys.stdout.write(s); return 0
        if cfg.mode=='rz':
            s=zend_extension_info(cfg.code)
            if s is None: sys.stdout.write(f"Exception: Zend Extension \"{cfg.code}\" does not exist\n"); return 1
            sys.stdout.write(s); return 0
        if cfg.mode=='ri':
            s=ri_text(cfg.code)
            if s is None: sys.stdout.write(f"Extension '{cfg.code}' not present.\n"); return 1
            sys.stdout.write(s); return 0
        if cfg.mode=='server': return run_server(cfg) or 0

        # Determine script/code mode.
        if cfg.mode=='run_code':
            script_name='Standard input code'; source_name='Command line code'; code=cfg.code; is_file=False
            script_argv=[script_name] + cfg.args
        elif cfg.mode=='process':
            script_name='Standard input code'; source_name='Command line code'; script_argv=[script_name]+cfg.args
            rt=Runtime(source_name, argv=script_argv, ini=cfg.ini)
            if cfg.begin: run_code(rt,cfg.begin,source_name,rt.global_env,False)
            proc_file_content=None
            if cfg.process_file:
                try: proc_file_content=open(cfg.process_file,'r',encoding='utf-8',errors='replace').read()
                except Exception:
                    sys.stderr.write(f"Could not open input file: {cfg.process_file}\n"); return 1
            argi=0
            for line in sys.stdin.read().splitlines():
                argi+=1; rt.global_env.set('argi', argi); rt.global_env.set('argn', line)
                if cfg.process_code is not None: run_code(rt,cfg.process_code,source_name,rt.global_env,False)
                else: run_code(rt,proc_file_content,cfg.process_file,rt.global_env,True)
            if cfg.end: run_code(rt,cfg.end,source_name,rt.global_env,False)
            return 0
        else:
            if cfg.file:
                if not os.path.exists(cfg.file):
                    if cfg.highlight: sys.stdout.write(f"Could not open input file: {cfg.file}\n"); return 0
                    sys.stderr.write(f"Could not open input file: {cfg.file}\n"); return 1
                with open(cfg.file,'r',encoding='utf-8',errors='replace') as f: code=f.read()
                script_name=cfg.file; source_name=cfg.file; is_file=True; script_argv=[cfg.file]+cfg.args
            else:
                code=sys.stdin.read(); script_name='Standard input code'; source_name='Standard input code'; is_file=True; script_argv=[script_name]+cfg.args

        if cfg.highlight:
            sys.stdout.write(highlight_file(code)); return 0
        if cfg.strip:
            sys.stdout.write(strip_comments_whitespace(code)); return 0
        if cfg.lint:
            return lint_code(code, source_name, is_file)
        ret=0
        for _ in range(cfg.repeat):
            rt=Runtime(source_name, filename=(cfg.file or source_name), argv=script_argv, ini=cfg.ini)
            try:
                run_code(rt, code, source_name, rt.global_env, is_file)
            except PHPExit as e:
                ret=e.code
                if ret!=0: return ret
        return ret
    except PHPExit as e:
        return e.code
    except KeyboardInterrupt:
        return 130

if __name__ == '__main__':
    sys.exit(main())
